package net.battlespades.bot;
import java.util.*;
import java.util.function.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotState.*;
import static net.battlespades.bot.BotMessages.Objective;
import static net.battlespades.bot.HordeCoordinator.*;
import static net.battlespades.bot.BotVectors.distance;

/** Gameplay-owner structural analysis under a measured per-call budget; failures degrade to ordinary hunting. */
public final class ZombieSiegeService implements AutoCloseable {
    public interface World extends RecoveryPlanning.World {default AutoCloseable subscribe(Consumer<Cell> listener){return null;}}
    private record Edit(long count,int x,int y){}private record Settled(Vector position,double at){}
    private record Analysis(Vector position,Siege info,double isolationAt,double planAt,boolean wantsPlan,Long edits){}
    private static final class Job {final int id;final Vector position;final boolean collapse;final int floor;final Long edits;int stage;StructureCollapse.ApproachJob approach;StructureCollapse.CutJob cut;Job(int id,Vector at,Long edits){this.id=id;position=at;this.edits=edits;collapse=false;floor=0;}Job(int id,Vector at,int floor,StructureCollapse.CutJob cut){this.id=id;position=at;this.floor=floor;this.cut=cut;collapse=true;edits=null;}}
    private final Thread owner=Thread.currentThread();private final HordeCoordinator coordinator=new HordeCoordinator();private final double budget;private final DoubleSupplier clock,budgetClock;private final BiConsumer<String,Throwable> failure;private double orderSeconds,lastFailure=Double.NEGATIVE_INFINITY;private final ArrayDeque<Edit> edits=new ArrayDeque<>();private long editCount;private int unseenEdits;private World watched;private AutoCloseable subscription;private long map=Long.MIN_VALUE,mode=Long.MIN_VALUE;private final LinkedHashMap<Integer,Analysis> analyses=new LinkedHashMap<>();private final ArrayDeque<Integer> queue=new ArrayDeque<>();private final LinkedHashMap<Integer,Settled> settled=new LinkedHashMap<>();private Job job;private Map<Integer,Order> lastOrders=Map.of();private final Map<String,Integer> stats=new LinkedHashMap<>();
    public ZombieSiegeService(double budget,DoubleSupplier clock,DoubleSupplier budgetClock,BiConsumer<String,Throwable> failure){this.budget=budget;this.clock=Objects.requireNonNull(clock);this.budgetClock=Objects.requireNonNull(budgetClock);this.failure=Objects.requireNonNull(failure);for(var key:List.of("analyses","plans","plans_found","isolated","max_pile","orders"))stats.put(key,0);}
    void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Zombie siege outside owner");}void count(String key){stats.merge(key,1,Integer::sum);}
    public HordeCoordinator coordinator(){owned();return coordinator;}public Map<String,Integer> stats(){owned();return Collections.unmodifiableMap(new LinkedHashMap<>(stats));}public Map<Integer,Order> lastOrders(){owned();return lastOrders;}
    public void reset(){owned();coordinator.reset();analyses.clear();job=null;queue.clear();settled.clear();lastOrders=Map.of();unwatch();}
    boolean watch(World world){unseenEdits=0;if(watched==world)return true;unwatch();var token=world.subscribe(cell->{if(watched==null)return;editCount++;if(edits.size()==512)edits.removeFirst();edits.addLast(new Edit(editCount,cell.x(),cell.y()));if(++unseenEdits>4096)unwatch();});if(token==null)return false;watched=world;subscription=token;return true;}
    void unwatch(){var token=subscription;watched=null;subscription=null;edits.clear();editCount++;if(token!=null)try{token.close();}catch(Exception error){report("zombie siege mutation subscription",error);}}
    void report(String message,Throwable error){try{failure.accept(message,error);}catch(RuntimeException ignored){/* Planning diagnostics must not escape into the simulation tick. */}}
    boolean editedNear(Analysis a){if(a.edits()==null||watched==null)return true;if(editCount==a.edits())return false;if(edits.isEmpty()||edits.getFirst().count()>a.edits()+1)return true;double reach=(a.info().approach()==null?0:a.info().approach().radius())+3;var it=edits.descendingIterator();while(it.hasNext()){var e=it.next();if(e.count()<=a.edits())break;if(Math.abs(e.x()+.5-a.position().x())<=reach&&Math.abs(e.y()+.5-a.position().y())<=reach)return true;}return false;}
    public List<Objective> objectives(long mapEpoch,long modeEpoch,boolean active,int zombieTeam,List<Member> zombies,List<Target> survivors,World world,double now){owned();try{return calculate(mapEpoch,modeEpoch,active,zombieTeam,zombies,survivors,world,now);}catch(RuntimeException error){double measured=clock.getAsDouble();if(measured-lastFailure>=60){lastFailure=measured;report("zombie siege planning failed; ordinary hunting retained",error);}reset();return List.of();}}
    List<Objective> calculate(long mapEpoch,long modeEpoch,boolean active,int team,List<Member> zombies,List<Target> survivors,World world,double now){double started=budgetClock.getAsDouble();if(map!=mapEpoch||mode!=modeEpoch||!active){if(map!=mapEpoch||mode!=modeEpoch||!analyses.isEmpty()||!lastOrders.isEmpty())reset();map=mapEpoch;mode=modeEpoch;if(!active)return List.of();}if(survivors.isEmpty()||zombies.stream().noneMatch(Member::bot)){lastOrders=Map.of();return List.of();}if(world!=null){boolean watching=watch(world);advanceAnalysis(world,survivors,zombies,now,started+Math.max(.25*budget,budget-orderSeconds),watching?editCount:null);}var sieges=new HashMap<Integer,Siege>();for(var s:survivors){var a=analyses.get(s.playerId());if(a!=null)sieges.put(s.playerId(),a.info());}double ordering=budgetClock.getAsDouble();lastOrders=coordinator.plan(zombies,survivors,sieges,now,world);orderSeconds+=.2*(Math.min(budgetClock.getAsDouble()-ordering,budget)-orderSeconds);stats.put("orders",lastOrders.size());stats.merge("max_pile",coordinator.metrics().maxPile(),Math::max);var result=new ArrayList<Objective>();for(var e:new TreeMap<>(lastOrders).entrySet()){var order=e.getValue();result.add(new Objective("zombie_order",team,order.goal(),order.zombieId(),order.roleCode(),List.of(),order.cells(),List.of(),order.stuckLevel(),order.targetId(),-1));}return List.copyOf(result);}
    void advanceAnalysis(World world,List<Target> survivors,List<Member> zombies,double now,double deadline,Long edits){var alive=new LinkedHashMap<Integer,Target>();for(var s:survivors)alive.put(s.playerId(),s);analyses.keySet().removeIf(id->!alive.containsKey(id));settled.keySet().removeIf(id->!alive.containsKey(id));for(var s:survivors){var previous=settled.get(s.playerId());if(previous==null||distance(previous.position(),s.position())>1.5)settled.put(s.playerId(),new Settled(s.position(),now));}if(job!=null&&!alive.containsKey(job.id))job=null;var hunters=zombies.stream().map(Member::position).toList();while(true){if(job==null){job=nextJob(world,alive,hunters,now,deadline,edits);if(job==null||budgetClock.getAsDouble()>=deadline)return;}while(true){boolean complete=advanceJob(job,world,hunters);if(complete){var finished=job;job=null;finish(finished,world,hunters,now);break;}if(budgetClock.getAsDouble()>=deadline)return;}if(budgetClock.getAsDouble()>=deadline)return;}}
    boolean advanceJob(Job job,World w,List<Vector> hunters){if(job.collapse)return job.cut.advance(24);if(job.stage==0){job.stage=1;return false;}if(job.stage==1){int feet=(int)Math.rint(job.position.z()+2.25);boolean above=StructureCollapse.hordeFloor(w,job.position,hunters,12)-feet>=3;job.approach=new StructureCollapse.ApproachJob(w,job.position,above?1200:600,2,4);job.stage=2;return false;}return job.approach.advance(6);}
    Job nextJob(World world,Map<Integer,Target> alive,List<Vector> hunters,double now,double deadline,Long edits){if(queue.isEmpty())queue.addAll(new TreeSet<>(alive.keySet()));int size=queue.size();for(int i=0;i<size;i++){int id=queue.removeFirst();var survivor=alive.get(id);if(survivor==null)continue;if(hunters.stream().noneMatch(h->distance(h,survivor.position())<=48)){analyses.remove(id);continue;}if(now-settled.get(id).at()<.75)continue;var a=analyses.get(id);boolean moved=a==null||distance(a.position(),survivor.position())>2;if(!moved&&now-a.isolationAt()>=2.5){if(a.info().approach()==null||editedNear(a))moved=true;else{assess(id,a.position(),a.info().approach(),world,hunters,now,a.edits());a=analyses.get(id);if(budgetClock.getAsDouble()>=deadline)return null;}}if(moved)return new Job(id,survivor.position(),edits);if(a.wantsPlan()&&now-a.planAt()>=6){var support=StructureCollapse.support(world,survivor.position());if(!support.isEmpty())return new Job(id,survivor.position(),a.info().floorZ(),new StructureCollapse.CutJob(world,support,a.info().floorZ(),2500,48,null));}}return null;}
    void finish(Job job,World world,List<Vector> hunters,double now){if(!job.collapse){count("analyses");var approach=job.approach.result();if(approach==null){analyses.put(job.id,new Analysis(job.position,new Siege(false,0,null,now,null,job.position),now,now,false,null));return;}assess(job.id,job.position,approach,world,hunters,now,job.edits);return;}count("plans");var a=analyses.get(job.id);if(a==null)return;var plan=job.cut.result();if(plan!=null)count("plans_found");var info=a.info();analyses.put(job.id,new Analysis(a.position(),new Siege(info.isolated(),job.floor,plan,now,info.approach(),info.position()),a.isolationAt(),now,a.wantsPlan(),a.edits()));}
    void assess(int id,Vector position,StructureCollapse.Approach approach,World world,List<Vector> hunters,double now,Long edits){var previous=analyses.get(id);boolean isolated=approach.closed()&&hunters.stream().noneMatch(h->approach.movesFrom(h)!=null);int floor=StructureCollapse.hordeFloor(world,position,hunters,12);boolean wants=isolated||worthPlanning(id,position,approach,floor,hunters);if(isolated&&(previous==null||!previous.info().isolated()||previous.info().approach()!=approach))count("isolated");StructureCollapse.Plan plan=null;double planAt=Double.NEGATIVE_INFINITY;if(wants&&previous!=null&&previous.info().plan()!=null&&distance(previous.position(),position)<=2&&now-previous.planAt()<6&&previous.info().plan().cut().stream().anyMatch(world::solid)){plan=previous.info().plan();planAt=previous.planAt();}else if(wants&&previous!=null&&previous.info().plan()==null&&previous.wantsPlan()&&distance(previous.position(),position)<=2&&now-previous.planAt()<6)planAt=previous.planAt();analyses.put(id,new Analysis(position,new Siege(isolated,floor,plan,now,approach,position),now,planAt,wants,edits));if(wants&&planAt==Double.NEGATIVE_INFINITY)queue.addFirst(id);}
    boolean worthPlanning(int id,Vector position,StructureCollapse.Approach a,int floor,List<Vector> hunters){if(floor-a.supportZ()<3)return false;if(coordinator.struggling(id))return true;var near=hunters.stream().filter(h->BotVectors.flat(h,position)<=24).toList();if(near.isEmpty())return false;for(var h:near){var moves=a.movesFrom(h);if(moves!=null&&moves*.8/8<=4)return false;}return true;}
    public List<Map<String,Object>> debugRows(){owned();return lastOrders.values().stream().map(o->Map.<String,Object>of("zombie",o.zombieId(),"target",o.targetId(),"role",o.role(),"cells",o.cells().size(),"stuck",o.stuckLevel())).toList();}
    @Override public void close(){reset();}
}
